-- Premier Zone seed: the player_stats table and its data (exported from the local pl_data database).
-- Run once on a new Postgres database, e.g. paste into Neon's SQL editor, or: psql "$DATABASE_URL" -f db/player_stats.sql
CREATE TABLE IF NOT EXISTS player_stats (
  id serial PRIMARY KEY,
  player text, nation text, pos text, age integer, mp integer, starts integer,
  min numeric, gls numeric, ast numeric, pk numeric, crdy numeric, crdr numeric, xg numeric, xag numeric,
  team text
);

ON CONFLICT (id) DO NOTHING;
ON CONFLICT (id) DO NOTHING;
ON CONFLICT (id) DO NOTHING;
ON CONFLICT (id) DO NOTHING;
ON CONFLICT (id) DO NOTHING;
ON CONFLICT (id) DO NOTHING;
SELECT setval(pg_get_serial_sequence('player_stats', 'id'), (SELECT max(id) FROM player_stats));
-- 587 rows
